<?php
require __DIR__.'/includes/bootstrap.php';require_login();if(is_admin())redirect('admin/index.php');$pdo=db();
if($_SERVER['REQUEST_METHOD']==='POST'){
 validate_csrf();$id=(int)($_POST['order_id']??0);$stmt=$pdo->prepare("UPDATE orders SET status='Concluída' WHERE id=? AND user_id=? AND status='A caminho'");$stmt->execute([$id,$_SESSION['user']['id']]);$ok=$stmt->rowCount()===1;$message=$ok?'Entrega confirmada. A fábrica já pode ver a atualização.':'Só é possível confirmar uma encomenda que esteja a caminho.';
 if(is_json_request()){json_response($ok,$message,$ok?200:422,['status'=>$ok?'Concluída':null,'refresh'=>$ok?['.order-grid']:[]]);}flash($ok?'success':'error',$message);redirect('orders.php');
}
$stmt=$pdo->prepare('SELECT o.*, GROUP_CONCAT(CONCAT(oi.product_name, " · ", oi.factory_name, " (", oi.quantity_tons, " t)") SEPARATOR ", ") AS items FROM orders o LEFT JOIN order_items oi ON oi.order_id = o.id WHERE o.user_id = ? GROUP BY o.id ORDER BY o.created_at DESC');$stmt->execute([$_SESSION['user']['id']]);$orders=$stmt->fetchAll();$pageTitle='As minhas encomendas';require __DIR__.'/includes/header.php';?>
<section class="section narrow"><p class="eyebrow">ÁREA DO CLIENTE</p><h1>As minhas encomendas</h1><p class="page-intro">Acompanhe todas as fases da preparação e entrega.</p>
<?php if(!$orders):?><div class="empty"><h2>Ainda não existem encomendas.</h2><a class="button button-primary" href="<?=url('products.php')?>">Ver produtos</a></div><?php else:?><div class="order-grid"><?php foreach($orders as $order):?><article class="panel order-card"><div><span class="status-pill status-<?=e(str_replace(' ','-',strtolower($order['status'])))?>"><?=e($order['status'])?></span><h2>#CP-<?=str_pad((string)$order['id'],5,'0',STR_PAD_LEFT)?></h2></div><p><?=e($order['items'])?></p><div class="order-progress" aria-label="Progresso da encomenda"><?php $steps=['Pendente','Aprovada','Pronta','A caminho','Concluída'];$current=array_search($order['status'],$steps,true);foreach($steps as $i=>$step):?><span class="<?=$current!==false&&$i<=$current?'done':''?>"><?=e($step)?></span><?php endforeach;?></div><dl><div><dt>Recolha prevista</dt><dd><?=e(date('d/m/Y',strtotime($order['collection_date'])))?> às <?=e(substr((string)($order['collection_time']??'09:00'),0,5))?></dd></div><div><dt>Total</dt><dd><?=number_format((float)$order['total'],2,',','.')?> €</dd></div></dl><div class="order-actions"><?php if($order['status']==='A caminho'&&!empty($order['tracking_url'])):?><a class="button button-primary" href="<?=e($order['tracking_url'])?>" target="_blank" rel="noopener noreferrer">Acompanhar localização</a><?php endif;?><a class="button" href="<?=url('transport-document.php?id='.(int)$order['id'])?>" target="_blank">Documento de transporte</a><a class="button" href="<?=url('help.php?order_id='.(int)$order['id'])?>">Pedir ajuda</a><?php if($order['status']==='A caminho'):?><form class="ajax-form" method="post" data-confirm="Confirma que recebeu a entrega?"><input type="hidden" name="csrf_token" value="<?=csrf_token()?>"><input type="hidden" name="order_id" value="<?=(int)$order['id']?>"><button class="button">Confirmar que a entrega foi feita</button><span class="save-feedback" role="status"></span></form><?php endif;?></div></article><?php endforeach;?></div><?php endif;?></section>
<?php require __DIR__.'/includes/footer.php';?>
